set -euo pipefail

SELF=${0##*/}

# 子命令按自身文件名推导（与生成期写入的  一致）
case "$SELF" in
  new-task.sh) CMD=task ;;
  open-pr.sh) CMD=pr ;;
  merge-pr.sh) CMD=merge ;;
  review.sh) CMD=review ;;
  status.sh) CMD=status ;;
  pipeline.sh) CMD='' ;;
  *)
    printf '未知入口: %s\n' "$SELF" >&2
    exit 2
    ;;
esac

# 脚本所在目录（绝对路径）
script_dir=$(cd "$(dirname "$0")" && pwd)

# 脚本所在仓根：git 顶层优先，取不到按 scripts/pipeline/ 布局上溯两级
script_repo_root=$(git -C "$script_dir" rev-parse --show-toplevel 2>/dev/null || true)
if [ -z "$script_repo_root" ]; then
  script_repo_root=$(cd "$script_dir/../.." && pwd)
fi

# 主工作区：git-common-dir 的父目录（相对路径按脚本所在仓根解析）；取不到就用脚本所在仓根
common=$(git -C "$script_repo_root" rev-parse --git-common-dir 2>/dev/null || true)
if [ -n "$common" ]; then
  case "$common" in
    /*) : ;;
    *) common="$script_repo_root/$common" ;;
  esac
  main_root=$(dirname "$common")
else
  main_root=$script_repo_root
fi

# 定位共享包：$DSH_PIPELINE_HOME → 主工作区 tools/ → 脚本所在仓 tools/，找到即停
CLI=''
tried=''
try_candidate() {
  if [ -z "$tried" ]; then
    tried=$1
  else
    tried="$tried、$1"
  fi
  if [ -z "$CLI" ] && [ -f "$1" ]; then
    CLI=$1
  fi
}

if [ -n "${DSH_PIPELINE_HOME:-}" ]; then
  try_candidate "$DSH_PIPELINE_HOME/bin/cli.mjs"
fi
try_candidate "$main_root/tools/node_modules/dsh-pipeline/bin/cli.mjs"
if [ "$script_repo_root" != "$main_root" ]; then
  try_candidate "$script_repo_root/tools/node_modules/dsh-pipeline/bin/cli.mjs"
fi

if [ -z "$CLI" ]; then
  printf '%s: 找不到共享包 dsh-pipeline（试过 %s）\n' "$SELF" "$tried" >&2
  exit 3
fi

# -C <dir> 与 -C=<dir> 翻译成 --root，其余参数原样透传
translated=()
while [ $# -gt 0 ]; do
  case "$1" in
    -C)
      if [ $# -ge 2 ]; then
        translated+=(--root "$2")
        shift 2
      else
        translated+=("$1")
